#!/usr/bin/env node
// The android/ project is regenerated by `cap add android` (it's gitignored),
// so any manual edit to AndroidManifest.xml is lost on the next regeneration.
// This script re-applies the one hardening change that matters here: the app
// now stores a user-supplied AI provider API key + full chat history in the
// WebView's localStorage, so android:allowBackup must be false — otherwise
// `adb backup` (or a cloud auto-backup) can pull that data off the device
// without root. Run this after every `cap add android` / `npm run android:add`.
const fs = require("fs");
const path = require("path");

const manifestPath = path.join(__dirname, "..", "android", "app", "src", "main", "AndroidManifest.xml");
if (!fs.existsSync(manifestPath)) {
  console.log("AndroidManifest.xml not found (android/ not added yet) — nothing to harden.");
  process.exit(0);
}

let xml = fs.readFileSync(manifestPath, "utf8");
const before = xml;
xml = xml.replace(/android:allowBackup="true"/, 'android:allowBackup="false"');

if (xml === before) {
  console.log("AndroidManifest.xml already hardened (allowBackup=false).");
} else {
  fs.writeFileSync(manifestPath, xml);
  console.log("Set android:allowBackup=\"false\" in AndroidManifest.xml.");
}
